import { PrismaPg } from "@prisma/adapter-pg";
import { z } from "zod";
import type { Prisma } from "../prisma/generated/client";
import { PrismaClient } from "../prisma/generated/client";

const DatabaseUrlSchema = z
  .string()
  .url()
  .refine(
    (url) => url.startsWith("postgresql://") || url.startsWith("postgres://"),
    {
      message: "DATABASE_URL must be a PostgreSQL connection string",
    },
  );

export type DatabaseClient = PrismaClient;

export interface ResolvePrismaClientOptions {
  connectionString?: string;
  envVar?: string;
  prismaOptions?: Prisma.PrismaClientOptions;
}

type AdapterClientOptions = Extract<
  Prisma.PrismaClientOptions,
  { adapter: unknown }
>;

export const DEFAULT_DATABASE_URL_ENV = "DATABASE_URL" as const;

type EnvRecord = Record<string, string | undefined>;

function resolveEnvironment(): EnvRecord | undefined {
  const globalProcess = (
    globalThis as {
      process?: { env?: EnvRecord };
    }
  ).process;

  if (globalProcess?.env) {
    return globalProcess.env;
  }

  const globalBun = (globalThis as { Bun?: { env?: EnvRecord } }).Bun;

  return globalBun?.env;
}

export function resolveConnectionString({
  connectionString,
  envVar = DEFAULT_DATABASE_URL_ENV,
}: ResolvePrismaClientOptions): string {
  if (connectionString) {
    return DatabaseUrlSchema.parse(connectionString);
  }

  const env = resolveEnvironment();

  // Prefer DATABASE_PUBLIC_URL for external access (CI, etc.)
  // Fall back to DATABASE_URL for local development
  const value = env?.DATABASE_PUBLIC_URL ?? env?.[envVar];

  return DatabaseUrlSchema.parse(value);
}

function buildClientOptions(
  connectionString: string,
  prismaOptions?: Prisma.PrismaClientOptions,
): AdapterClientOptions {
  const {
    adapter,
    accelerateUrl: _accelerateUrl,
    ...restOptions
  } = prismaOptions ?? {};

  const clientOptions = {
    ...restOptions,
    adapter: adapter ?? new PrismaPg({ connectionString }),
  } satisfies AdapterClientOptions;

  return clientOptions;
}

export function createPrismaClient(
  options: string | ResolvePrismaClientOptions = {},
): PrismaClient {
  const resolvedOptions =
    typeof options === "string" ? { connectionString: options } : options;

  const connectionString = resolveConnectionString(resolvedOptions);

  return new PrismaClient(
    buildClientOptions(connectionString, resolvedOptions.prismaOptions),
  );
}

export function getPrismaClient(
  options: string | ResolvePrismaClientOptions = {},
): PrismaClient {
  return createPrismaClient(options);
}
